package com.hrflow.platform.leave;
import com.hrflow.platform.common.ApiModels.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.time.LocalDate;
@RestController @RequestMapping("/api/v1/leave-requests") @RequiredArgsConstructor public class LeaveController {private final LeaveService service;
 @PostMapping @ResponseStatus(HttpStatus.CREATED)LeaveView create(@Valid @RequestBody LeaveInput i,Authentication a){return service.create(i,a.getName());}@GetMapping("/mine")Page<LeaveView> mine(Authentication a,@PageableDefault(sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return service.mine(a.getName(),p);}
 @GetMapping @PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER')")Page<LeaveView> list(@RequestParam(required=false)LeaveStatus status,@RequestParam(required=false)Long employeeId,@RequestParam(required=false)Long departmentId,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to,Authentication a,@PageableDefault(sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return service.list(status,employeeId,departmentId,from,to,a,p);}
 @GetMapping("/{id}")LeaveView get(@PathVariable Long id,Authentication a){return service.get(id,a);}@PatchMapping("/{id}/approve")@PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER')")LeaveView approve(@PathVariable Long id,@Valid @RequestBody Decision d,Authentication a){return service.approve(id,d,a);}@PatchMapping("/{id}/reject")@PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER')")LeaveView reject(@PathVariable Long id,@Valid @RequestBody Decision d,Authentication a){return service.reject(id,d,a);}@PatchMapping("/{id}/cancel")LeaveView cancel(@PathVariable Long id,Authentication a){return service.cancel(id,a.getName());}}
